import React, { useRef, useEffect, useState } from "react";
import jaxImage from "../assets/jaxreference1.png";

const initialImages = [
  {
    id: "jax1",
    src: jaxImage,
    x: 100,
    y: 100,
    width: 300,
    height: 200,
  },
];

export default function ConceptBoard() {
  const canvasRef = useRef(null);
  const [images, setImages] = useState(initialImages);
  const [draggingId, setDraggingId] = useState(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [canvasOffset, setCanvasOffset] = useState({ x: 0, y: 0 });
  const [scale, setScale] = useState(1);
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  const handleMouseDown = (e, id) => {
    e.stopPropagation();
    setDraggingId(id);
    const image = images.find((img) => img.id === id);
    setDragOffset({
      x: e.clientX / scale - image.x,
      y: e.clientY / scale - image.y,
    });
  };

  const handleMouseUp = () => {
    setDraggingId(null);
    setIsPanning(false);
  };

  const handleMouseMove = (e) => {
    if (draggingId) {
      setImages((prevImages) =>
        prevImages.map((img) =>
          img.id === draggingId
            ? {
                ...img,
                x: e.clientX / scale - dragOffset.x,
                y: e.clientY / scale - dragOffset.y,
              }
            : img
        )
      );
    } else if (isPanning) {
      setCanvasOffset((prev) => ({
        x: prev.x + (e.clientX - panStart.x),
        y: prev.y + (e.clientY - panStart.y),
      }));
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  const handleWheel = (e) => {
    e.preventDefault();
    const zoomSpeed = 0.001;
    setScale((prevScale) =>
      Math.min(3, Math.max(0.25, prevScale - e.deltaY * zoomSpeed))
    );
  };

  const handleBackgroundMouseDown = (e) => {
    if (e.button !== 0) return;
    setIsPanning(true);
    setPanStart({ x: e.clientX, y: e.clientY });
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    canvas.addEventListener("wheel", handleWheel, { passive: false });
    return () => canvas.removeEventListener("wheel", handleWheel);
  }, []);

  return (
    <div
      ref={canvasRef}
      onMouseDown={handleBackgroundMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      style={{
        width: "100%",
        height: "calc(100vh - 160px)",
        backgroundColor: "#1a1a1a",
        overflow: "hidden",
        position: "relative",
        cursor: isPanning ? "grabbing" : "grab",
      }}
    >
      <div
        style={{
          transform: `translate(${canvasOffset.x}px, ${canvasOffset.y}px) scale(${scale})`,
          transformOrigin: "0 0",
          position: "absolute",
          top: 0,
          left: 0,
        }}
      >
        {images.map((img) => (
          <img
            key={img.id}
            src={img.src}
            alt=""
            style={{
              position: "absolute",
              left: img.x,
              top: img.y,
              width: img.width,
              height: img.height,
              cursor: "move",
              borderRadius: "8px",
              boxShadow: "0 4px 20px rgba(0,0,0,0.5)",
              userSelect: "none",
              transition: draggingId === img.id ? "none" : "box-shadow 0.2s",
            }}
            draggable={false}
            onMouseDown={(e) => handleMouseDown(e, img.id)}
          />
        ))}
      </div>
    </div>
  );
}
